package org.basaltmc.server.runtime.registry

import org.basaltmc.server.runtime.registry.VanillaBiomes.AmbientAddition
import org.basaltmc.server.runtime.registry.VanillaBiomes.AmbientMood
import org.basaltmc.server.runtime.registry.VanillaBiomes.AmbientParticle
import org.basaltmc.server.runtime.registry.VanillaBiomes.BiomeAttribute
import org.basaltmc.server.runtime.registry.VanillaBiomes.Entry
import org.basaltmc.server.runtime.registry.VanillaBiomes.MusicTrack

/**
 * Nether and end biome entries, split out of [VanillaBiomes] for file size. Both groups are
 * generated by small factory functions instead of a literal list, because nether and end biomes
 * repeat most of their fields.
 *
 * Order matters: [NETHER_ENTRIES] then [END_ENTRIES] is the tail of the sequence in
 * [VanillaBiomes.ALL], and that sequence is the network id a chunk's biome palette references.
 */
internal object VanillaNetherEndBiomes {
    internal val NETHER_ENTRIES: List<Entry> =
        listOf(
            netherBiome(
                path = "nether_wastes",
                fogColor = "#330808",
                ambientPath = "nether_wastes",
                musicPath = "nether_wastes",
            ),
            netherBiome(
                path = "warped_forest",
                fogColor = "#1a051a",
                ambientPath = "warped_forest",
                musicPath = "warped_forest",
                particle = AmbientParticle("minecraft:warped_spore", 0.01428f),
            ),
            netherBiome(
                path = "crimson_forest",
                fogColor = "#330303",
                ambientPath = "crimson_forest",
                musicPath = "crimson_forest",
                particle = AmbientParticle("minecraft:crimson_spore", 0.025f),
            ),
            netherBiome(
                path = "soul_sand_valley",
                fogColor = "#1b4745",
                ambientPath = "soul_sand_valley",
                musicPath = "soul_sand_valley",
                particle = AmbientParticle("minecraft:ash", 0.00625f),
            ),
            netherBiome(
                path = "basalt_deltas",
                fogColor = "#685f70",
                ambientPath = "basalt_deltas",
                musicPath = "basalt_deltas",
                particle = AmbientParticle("minecraft:white_ash", 0.118093334f),
            ),
        )

    internal val END_ENTRIES: List<Entry> =
        listOf(
            endBiome("the_end"),
            endBiome("end_highlands"),
            endBiome("end_midlands"),
            endBiome("small_end_islands"),
            endBiome("end_barrens"),
        )

    private fun netherBiome(
        path: String,
        fogColor: String,
        ambientPath: String,
        musicPath: String,
        particle: AmbientParticle? = null,
    ): Entry =
        Entry(
            path,
            temperature = 2.0f,
            downfall = 0.0f,
            hasPrecipitation = false,
            waterColor = "#3f76e4",
            attributes =
                buildMap {
                    put(
                        "minecraft:audio/ambient_sounds",
                        BiomeAttribute.Sounds(
                            loop = "minecraft:ambient.$ambientPath.loop",
                            mood = AmbientMood("minecraft:ambient.$ambientPath.mood"),
                            addition = AmbientAddition("minecraft:ambient.$ambientPath.additions"),
                        ),
                    )
                    put(
                        "minecraft:audio/background_music",
                        BiomeAttribute.Music(
                            mapOf("default" to MusicTrack("minecraft:music.nether.$musicPath", 12000, 24000)),
                        ),
                    )
                    particle?.let {
                        put("minecraft:visual/ambient_particles", BiomeAttribute.Particles(listOf(it)))
                    }
                    put("minecraft:visual/fog_color", BiomeAttribute.Color(fogColor))
                },
        )

    private fun endBiome(path: String): Entry =
        Entry(
            path,
            temperature = 0.5f,
            downfall = 0.5f,
            hasPrecipitation = false,
            waterColor = "#3f76e4",
        )
}
